local M={}; local function call(fn) if type(fn)~="function" then return nil end; local ok,v=pcall(fn); return ok and v or nil end; function M.read(mobile,mcu,cfg) local imei=mobile and call(mobile.imei) or nil; local serial=cfg and cfg.serial_number or nil; if not serial and mcu then local uid=call(mcu.unique_id); if uid and type(uid.toHex)=="function" then serial=uid:toHex() end end; return {serial_number=serial,imei=imei} end; return M
